<?php
namespace Tests\Feature;use App\Models\ServiceCategory;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;class ServiceCategoryTest extends TestCase{    use RefreshDatabase;    protected function setUp(): void    {        parent::setUp();        $this->user = User::factory()->create();        Sanctum::actingAs($this->user, ["*"]);        $this->serviceCategoryData = [            "name" => "Categoria de Teste",            "slug" => "categoria-de-teste",            "description" => "Descrição da categoria",            "is_active" => true,        ];    }    /**     * Teste: listar categorias de serviço com sucesso (index).     */    public function test_list_service_categories_success(): void    {        foreach (range(1, 3) as $i) {            ServiceCategory::create([                "name" => "Categoria {$i}",                "slug" => "categoria-{$i}",            ]);        }        $response = $this->get("/api/v1/service-categories");        $response->assertStatus(200);        $response->assertJson([            "success" => true,            "status" => 200,        ]);        $response->assertJsonStructure([            "data" => [                "items",                "pagination",            ],            "message",            "status",        ]);    }    /**     * Teste: buscar categoria de serviço por ID com sucesso (show).     */    public function test_show_service_category_success(): void    {        $serviceCategory = ServiceCategory::create([            "name" => "Categoria para Buscar",            "slug" => "categoria-para-buscar",        ]);        $response = $this->get("/api/v1/service-categories/{$serviceCategory->id}");        $response->assertStatus(200);        $response->assertJson([            "success" => true,            "status" => 200,            "message" => "Categoria de serviço encontrada.",        ]);    }    /**     * Teste: buscar categoria de serviço inexistente retorna 404.     */    public function test_show_service_category_not_found(): void    {        $response = $this->get("/api/v1/service-categories/99999");        $response->assertStatus(404);        $response->assertJson([            "success" => false,            "status" => 404,        ]);    }    /**     * Teste: criar categoria de serviço com sucesso (store).     */    public function test_store_service_category_success(): void    {        $response = $this->post("/api/v1/service-categories", $this->serviceCategoryData);        $response->assertStatus(201);        $response->assertJson([            "success" => true,            "status" => 201,            "message" => "Categoria de serviço criada com sucesso.",        ]);        $this->assertDatabaseHas("service_categories", [            "name" => "Categoria de Teste",        ]);    }    /**     * Teste: atualizar categoria de serviço com sucesso (update).     */    public function test_update_service_category_success(): void    {        $serviceCategory = ServiceCategory::create([            "name" => "Categoria Original",            "slug" => "categoria-original",        ]);        $updateData = [            "name" => "Categoria Atualizada",        ];        $response = $this->put("/api/v1/service-categories/{$serviceCategory->id}", $updateData);        $response->assertStatus(200);        $response->assertJson([            "success" => true,            "message" => "Categoria de serviço atualizada com sucesso.",        ]);        $this->assertDatabaseHas("service_categories", [            "name" => "Categoria Atualizada",        ]);    }    /**     * Teste: atualizar categoria de serviço inexistente retorna 404.     */    public function test_update_service_category_not_found(): void    {        $response = $this->put("/api/v1/service-categories/99999", [            "name" => "Novo Nome",        ]);        $response->assertStatus(404);        $response->assertJson([            "success" => false,            "status" => 404,        ]);    }    /**     * Teste: excluir categoria de serviço com sucesso (destroy).     */    public function test_destroy_service_category_success(): void    {        $serviceCategory = ServiceCategory::create([            "name" => "Categoria para Excluir",            "slug" => "categoria-para-excluir",        ]);        $response = $this->delete("/api/v1/service-categories/{$serviceCategory->id}");        $response->assertStatus(200);        $response->assertJson([            "success" => true,            "message" => "Categoria de serviço removida com sucesso.",        ]);        $this->assertDatabaseMissing("service_categories", [            "name" => "Categoria para Excluir",        ]);    }    /**     * Teste: excluir categoria de serviço inexistente retorna 404.     */    public function test_destroy_service_category_not_found(): void    {        $response = $this->delete("/api/v1/service-categories/99999");        $response->assertStatus(404);        $response->assertJson([            "success" => false,            "status" => 404,        ]);    }    /**     * Teste: rota sem autenticação retorna 401.     */    public function test_unauthenticated_request_returns_401(): void    {                $this->app['auth']->forgetGuards();

        $response = $this->get("/api/v1/service-categories");        $response->assertStatus(401);    }}